action.command:
node -e "
const fs = require('fs');
const path = require('path');
let data = '';
process.stdin.on('data', d => data += d);
process.stdin.on('end', () => {
  try {
    const event = JSON.parse(data);
    const filePath = event.file || '';
    // Map src file to test counterpart
    const testPath = filePath.replace(/src[/\\\\]/, 'tests/unit/').replace(/\\.tsx?$/, '.test.ts');
    const altTestPath = filePath.replace(/\\.tsx?$/, '.test.ts');
    const exists = fs.existsSync(testPath) || fs.existsSync(altTestPath);
    if (exists) {
      const tp = fs.existsSync(testPath) ? testPath : altTestPath;
      console.log('Running tests for: ' + tp);
    }
  } catch {}
});
"
npx vitest run --reporter=verbose 2>&1 | tail -30
